suppressPackageStartupMessages(library(DIRECTNET))
stopifnot(as.character(packageVersion('DIRECTNET')) == '0.0.1')
set.seed(42)
x <- matrix(rnorm(80),20,4)
y <- rnorm(20)
legacy <- tryCatch({xgboost::xgb.train(params=list(objective='reg:linear',nthread=1), data=xgboost::xgb.DMatrix(x,label=y), nrounds=1); 'passed'},error=function(e) conditionMessage(e))
modern <- tryCatch({xgboost::xgb.train(params=list(objective='reg:squarederror',nthread=1), data=xgboost::xgb.DMatrix(x,label=y), nrounds=1); 'passed'},error=function(e) conditionMessage(e))
options(Seurat.object.assay.version='v3')
a <- SeuratObject::CreateAssayObject(counts=Matrix::Matrix(matrix(sample.int(5,24,TRUE),6,4,dimnames=list(paste0('gene',1:6),paste0('cell',1:4))),sparse=TRUE))
stopifnot('counts' %in% slotNames(a))
object <- SeuratObject::CreateSeuratObject(counts=a)
stopifnot('counts' %in% slotNames(object@assays$RNA))
jsonlite::write_json(list(DIRECTNET=as.character(packageVersion('DIRECTNET')),cicero=as.character(packageVersion('cicero')),xgboost=as.character(packageVersion('xgboost')),Seurat=as.character(packageVersion('Seurat')),legacy_reg_linear=legacy,modern_reg_squarederror=modern,v3_Assay_counts_slot=TRUE), 'Analysis/ATAC/Regulatory_Methods/envs/installation-20261023/directnet-smoke.json',auto_unbox=TRUE,pretty=TRUE)
write.table(as.data.frame(installed.packages()[,c('Package','Version','LibPath')]),'Analysis/ATAC/Regulatory_Methods/envs/installation-20261023/directnet-R-packages.tsv',sep='\t',row.names=FALSE,quote=FALSE)
writeLines(capture.output(sessionInfo()),'Analysis/ATAC/Regulatory_Methods/envs/installation-20261023/directnet-sessionInfo.txt')
